=== web/ReservationRequestParser.java
     1	package pousada.web;
     2	
     3	import com.fasterxml.jackson.core.JsonProcessingException;
     4	import com.fasterxml.jackson.databind.JsonNode;
     5	import com.fasterxml.jackson.databind.ObjectMapper;
     6	import pousada.domain.ApiException;
     7	import pousada.domain.ErrorCode;
     8	import pousada.domain.NewReservation;
     9	import pousada.domain.RatePlan;
    10	
    11	import java.time.LocalDate;
    12	import java.time.format.DateTimeParseException;
    13	
    14	/** Lê e valida o corpo do POST /reservations. */
    15	final class ReservationRequestParser {
    16	    private final ObjectMapper mapper;
    17	
    18	    ReservationRequestParser(ObjectMapper mapper) {
    19	        this.mapper = mapper;
    20	    }
    21	
    22	    NewReservation parse(String body) {
    23	        JsonNode json;
    24	        try {
    25	            json = mapper.readTree(body);
    26	        } catch (JsonProcessingException e) {
    27	            throw invalid("O corpo não é um JSON válido");
    28	        }
    29	        if (json == null || !json.isObject()) {
    30	            throw invalid("O corpo deve ser um objeto JSON");
    31	        }
    32	        LocalDate checkIn = date(json, "checkIn");
    33	        LocalDate checkOut = date(json, "checkOut");
    34	        if (!checkOut.isAfter(checkIn)) {
    35	            throw invalid("A saída deve ser depois da entrada");
    36	        }
    37	        int guests = integer(json, "guests");
    38	        if (guests < 1) {
    39	            throw invalid("É preciso pelo menos um hóspede");
    40	        }
    41	        return new NewReservation(integer(json, "roomNumber"), text(json, "guestName"),
    42	                text(json, "guestEmail"), text(json, "guestCpf"), checkIn, checkOut, guests, ratePlan(json));
    43	    }
    44	
    45	    private static String text(JsonNode json, String field) {
    46	        JsonNode node = json.get(field);
    47	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    48	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    49	        }
    50	        return node.asText();
    51	    }
    52	
    53	    private static int integer(JsonNode json, String field) {
    54	        JsonNode node = json.get(field);
    55	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    56	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    57	        }
    58	        return node.asInt();
    59	    }
    60	
    61	    private static LocalDate date(JsonNode json, String field) {
    62	        String text = text(json, field);
    63	        try {
    64	            return LocalDate.parse(text);
    65	        } catch (DateTimeParseException e) {
    66	            throw invalid("Data inválida em " + field + ": " + text);
    67	        }
    68	    }
    69	
    70	    private static RatePlan ratePlan(JsonNode json) {
    71	        String text = text(json, "ratePlan");
    72	        try {
    73	            return RatePlan.valueOf(text);
    74	        } catch (IllegalArgumentException e) {
    75	            throw invalid("Plano de tarifa inválido: " + text);
    76	        }
    77	    }
    78	
    79	    private static ApiException invalid(String message) {
    80	        return new ApiException(ErrorCode.INVALID_REQUEST, message);
    81	    }
    82	}
