    16	    /** R$ 1.234,56 */
    17	    static String money(BigDecimal value) {
    18	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.ROOT);
    19	        symbols.setGroupingSeparator('.');
    20	        symbols.setDecimalSeparator(',');
    21	        return "R$ " + new DecimalFormat("#,##0.00", symbols).format(value);
