     9	public final class ReceiptText {
    10	    private ReceiptText() {
    11	    }
    12	
    13	    public static String format(Receipt receipt) {
    14	        List<String> lines = new ArrayList<>();
    15	        lines.add(receipt.title() + " nº " + receipt.reservationId());
    16	        lines.add("Hóspede: " + receipt.guestName() + " (CPF " + receipt.guestCpf() + ")");
    17	        lines.add("Quarto: " + receipt.roomNumber() + " (" + receipt.roomType() + ")");
    18	        lines.add("Entrada: " + BrazilianFormat.date(receipt.checkIn())
    19	                + " | Saída: " + BrazilianFormat.date(receipt.checkOut())
    20	                + " | " + receipt.nights() + (receipt.nights() == 1 ? " diária" : " diárias"));
    21	        lines.add("Diárias: " + BrazilianFormat.money(receipt.subtotal()));
    22	        if (receipt.discount().compareTo(BigDecimal.ZERO) > 0) {
    23	            lines.add("Desconto: " + BrazilianFormat.money(receipt.discount()));
    24	        }
    25	        lines.add("Total: " + BrazilianFormat.money(receipt.total()));
    26	        return String.join("\n", lines);
    27	    }
    28	}
