     1	package pousada.service;
     2	
     3	import pousada.domain.ApiException;
     4	import pousada.domain.ErrorCode;
     5	import pousada.domain.Message;
     6	import pousada.domain.NewReservation;
     7	import pousada.domain.Receipt;
     8	import pousada.domain.Reservation;
     9	import pousada.domain.Room;
    10	import pousada.domain.RoomCatalog;
    11	import pousada.persistence.Database;
    12	import pousada.persistence.Tx;
    13	
    14	import java.util.List;
    15	import java.util.function.BiFunction;
    16	import java.util.function.Consumer;
    17	
    18	public class ReservationService {
    19	    private final Database database;
    20	    private final RoomCatalog rooms;
    21	
    22	    public ReservationService(Database database, RoomCatalog rooms) {
    23	        this.database = database;
    24	        this.rooms = rooms;
    25	    }
    26	
    27	    public List<Room> rooms() {
    28	        return rooms.all();
    29	    }
    30	
    31	    public Reservation create(NewReservation request) {
    32	        Room room = rooms.find(request.roomNumber()).orElseThrow(() ->
    33	                new ApiException(ErrorCode.ROOM_NOT_FOUND, "Quarto " + request.roomNumber() + " não existe"));
    34	        if (request.guests() > room.capacity()) {
    35	            throw new ApiException(ErrorCode.CAPACITY_EXCEEDED,
    36	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    37	        }
    38	        return database.inTransaction(tx -> {
    39	            tx.lockRoom(room.number());
    40	            if (tx.reservations().hasConflict(room.number(), request.checkIn(), request.checkOut())) {
    41	                throw new ApiException(ErrorCode.ROOM_UNAVAILABLE,
    42	                        "O quarto " + room.number() + " já está reservado em alguma dessas noites");
    43	            }
    44	            return tx.reservations().insert(Reservation.open(room, request));
    45	        });
    46	    }
    47	
    48	    public Reservation get(long id) {
    49	        return database.inTransaction(tx -> tx.reservations().find(id).orElseThrow(() -> notFound(id)));
    50	    }
    51	
    52	    public Reservation confirm(long id) {
    53	        return change(id, Reservation::confirm, (tx, r) -> {
    54	            tx.messages().save(ConfirmationEmail.build(r, receiptOf(r)));
    55	            return r;
    56	        });
    57	    }
    58	
    59	    public Reservation cancel(long id) {
    60	        return change(id, Reservation::cancel, (tx, r) -> r);
    61	    }
    62	
    63	    public Reservation checkIn(long id) {
    64	        return change(id, Reservation::registerCheckIn, (tx, r) -> r);
    65	    }
    66	
    67	    public Receipt checkOut(long id) {
    68	        return change(id, Reservation::registerCheckOut, (tx, r) -> receiptOf(r));
    69	    }
    70	
    71	    /** Segunda via do comprovante, só para reserva paga. */
    72	    public Receipt document(long id) {
    73	        Reservation reservation = get(id);
    74	        reservation.requirePaid();
    75	        return receiptOf(reservation);
    76	    }
    77	
    78	    public List<Message> messages() {
    79	        return database.inTransaction(tx -> tx.messages().all());
    80	    }
    81	
    82	    /** Trava a reserva, aplica a mudança de situação, grava e deixa o caso completar o que é dele. */
    83	    private <R> R change(long id, Consumer<Reservation> action, BiFunction<Tx, Reservation, R> then) {
    84	        return database.inTransaction(tx -> {
    85	            Reservation reservation = tx.reservations().findForUpdate(id).orElseThrow(() -> notFound(id));
    86	            action.accept(reservation);
    87	            tx.reservations().update(reservation);
    88	            return then.apply(tx, reservation);
    89	        });
    90	    }
    91	
    92	    private Receipt receiptOf(Reservation reservation) {
    93	        return Receipt.of(reservation, rooms.get(reservation.roomNumber()));
    94	    }
    95	
    96	    private static ApiException notFound(long id) {
    97	        return new ApiException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe");
    98	    }
    99	}

