     8	/** O formato comum a todos os relatórios: título, cabeçalho, linhas e total. */
     9	public final class CsvWriter {
    10	    private CsvWriter() {
    11	    }
    12	
    13	    public static String write(Report report, Period period, ReportTable table) {
    14	        List<List<String>> lines = new ArrayList<>();
    15	        lines.add(List.of(Establishment.NAME, report.name(), period.label()));
    16	        lines.add(table.header());
    17	        lines.addAll(table.rows());
    18	        lines.add(table.total());
    19	        StringBuilder csv = new StringBuilder();
    20	        for (List<String> line : lines) {
    21	            csv.append(String.join(",", line.stream().map(CsvWriter::escape).toList())).append('\n');
    22	        }
    23	        return csv.toString();
    24	    }
    25	
    26	    private static String escape(String value) {
    27	        if (value.contains(",") || value.contains("\"") || value.contains("\n")) {
    28	            return "\"" + value.replace("\"", "\"\"") + "\"";
    29	        }
    30	        return value;
    31	    }
    32	}
