     9	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    10	        BigDecimal subtotal = Money.ZERO;
    11	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    12	            subtotal = subtotal.add(Season.of(night).apply(room.nightlyRate()));
    13	        }
    14	        subtotal = Money.round(subtotal);
    15	        BigDecimal discount = plan.discountOn(subtotal);
    16	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    17	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    18	    }
