     8	import java.util.function.Function;
     9	
    10	public class Database implements AutoCloseable {
    11	    private final HikariDataSource dataSource;
    12	
    13	    public Database(String url, String user, String password) {
    14	        HikariConfig config = new HikariConfig();
    15	        config.setJdbcUrl(url);
    16	        config.setUsername(user);
    17	        config.setPassword(password);
    18	        config.setMaximumPoolSize(10);
    19	        config.setInitializationFailTimeout(60_000);
    20	        this.dataSource = new HikariDataSource(config);
    21	    }
    22	
    23	    /** Cria o que falta no banco; pode rodar mais de uma vez e por mais de um processo. */
    24	    public void createSchema() {
    25	        inTransaction(tx -> {
    26	            tx.lockSchemaCreation();
    27	            Schema.create(tx.connection());
    28	            return null;
    29	        });
    30	    }
    31	
    32	    /** Roda o trabalho numa transação: confirma se terminar bem, desfaz se der qualquer erro. */
    33	    public <T> T inTransaction(Function<Tx, T> work) {
    34	        try (Connection connection = dataSource.getConnection()) {
    35	            connection.setAutoCommit(false);
    36	            try {
    37	                T result = work.apply(new Tx(connection));
    38	                connection.commit();
    39	                return result;
    40	            } catch (RuntimeException | Error e) {
    41	                connection.rollback();
    42	                throw e;
    43	            }
    44	        } catch (SQLException e) {
    45	            throw new IllegalStateException("Erro no banco de dados", e);
    46	        }
    47	    }
    48	
    49	    @Override
    50	    public void close() {
    51	        dataSource.close();
    52	    }
    53	}
