 26	class ReportsTest {
 27	    private final RoomCatalog rooms = RoomCatalog.standard();
 28	    private final List<Reservation> all = new ArrayList<>();
 29	    private long nextId = 1;
 30	
 31	    private final ReportSource source = new ReportSource() {
 32	        @Override
 33	        public List<Reservation> occupying(LocalDate night) {
 34	            return all.stream().filter(r -> r.occupies(night))
 35	                    .sorted(Comparator.comparingInt(Reservation::roomNumber)).toList();
 36	        }
 37	
 38	        @Override
 39	        public List<Reservation> startingIn(Period p) {
 40	            return all.stream().filter(r -> !r.checkIn().isBefore(p.from()) && r.checkIn().isBefore(p.toExclusive()))
 41	                    .sorted(Comparator.comparing(Reservation::checkIn).thenComparing(Reservation::id)).toList();
 42	        }
 43	    };
 44	
 45	    private Reservation add(int room, String in, String out, int guests, RatePlan plan) {
 46	        Reservation open = Reservation.open(rooms.get(room), new NewReservation(room, "H", "h@x.com", "1",
 47	                LocalDate.parse(in), LocalDate.parse(out), guests, plan));
 48	        Reservation r = new Reservation(nextId++, room, "H", "h@x.com", "1", open.checkIn(), open.checkOut(),
 49	                guests, plan, open.nights(), open.subtotal(), open.discount(), open.total(),
 50	                open.status(), open.amountPaid(), null);
 51	        all.add(r);
 52	        return r;
 53	    }
