 99	        cancelled.cancel();
100	        assertEquals("""
101	                Pousada Maré Alta,tourism-tax,2027-03
102	                reservation,room,check_in,check_out,guests,nights,tax
103	                1,201,2027-03-10,2027-03-13,2,3,27.00
104	                total,27.00
105	                """, render(new TourismTaxReport(new BigDecimal("4.50")), "2027-03"));
106	    }
107	
108	    @Test
109	    void ratePlansAlwaysListEveryPlan() {
110	        add(101, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD).confirm();
111	        assertEquals("""
112	                Pousada Maré Alta,rate-plans,2027-03
113	                rate_plan,reservations,amount
114	                STANDARD,1,499.80
115	                NON_REFUNDABLE,0,0.00
116	                total,1,499.80
117	                """, render(new RatePlanReport(), "2027-03"));
118	    }
