120	    @Test
121	    void periodsAreValidated() {
122	        assertEquals("2027-07-10", PeriodKind.DAY.read("2027-07-10").label());
123	        for (String bad : new String[]{null, "", "2027-7", "2027-07"}) {
124	            org.junit.jupiter.api.Assertions.assertThrows(pousada.domain.ApiException.class,
125	                    () -> PeriodKind.DAY.read(bad));
126	        }
