177	        assertEquals(Season.HIGH, Season.of(LocalDate.parse("2027-12-15")));
178	        assertEquals(Season.HIGH, Season.of(LocalDate.parse("2028-02-29")));
179	        assertEquals(Season.LOW, Season.of(LocalDate.parse("2028-03-01")));
180	        assertEquals(Season.HIGH, Season.of(LocalDate.parse("2027-07-31")));
181	        assertEquals(Season.LOW, Season.of(LocalDate.parse("2027-08-01")));
182	    }
