193	    @Test
194	    void lifecycleFollowsTheAllowedOrder() {
195	        Reservation r = reservation(201, "2027-03-10", "2027-03-12", RatePlan.STANDARD);
196	        assertThrows(ApiException.class, r::registerCheckIn);
197	        r.confirm();
198	        assertEquals(r.total(), r.amountPaid());
199	        assertThrows(ApiException.class, r::confirm);
200	        assertThrows(ApiException.class, r::registerCheckOut);
201	        r.registerCheckIn();
