  3	import com.fasterxml.jackson.databind.JsonNode;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import io.javalin.Javalin;
  6	import org.junit.jupiter.api.AfterAll;
  7	import org.junit.jupiter.api.BeforeAll;
  8	import org.junit.jupiter.api.Test;
  9	import pousada.domain.RoomCatalog;
 10	import pousada.persistence.Database;
 11	import pousada.report.OccupancyReport;
 12	import pousada.report.RatePlanReport;
 13	import pousada.report.ReportService;
 14	import pousada.report.RevenueReport;
 15	import pousada.report.TourismTaxReport;
 16	import pousada.service.ReservationService;
 17	import pousada.web.Api;
 18	
 19	import java.math.BigDecimal;
 20	import java.net.URI;
 21	import java.net.http.HttpClient;
 22	import java.net.http.HttpRequest;
 23	import java.net.http.HttpResponse;
 24	import java.sql.Connection;
 25	import java.sql.DriverManager;
 26	import java.sql.Statement;
 27	import java.util.List;
 28	import java.util.UUID;
 29	
 30	import static org.junit.jupiter.api.Assertions.assertEquals;
 31	import static org.junit.jupiter.api.Assertions.assertTrue;
 32	import static org.junit.jupiter.api.Assumptions.assumeTrue;
 33	
 34	/** Roda contra o PostgreSQL de DB_URL, num schema só dele que some no fim. */
 35	class ApiTest {
 36	    private static final ObjectMapper JSON = new ObjectMapper()
 37	            .enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)
 38	            .setNodeFactory(com.fasterxml.jackson.databind.node.JsonNodeFactory.withExactBigDecimals(true));
 39	    private static final HttpClient HTTP = HttpClient.newHttpClient();
 40	    private static String schema;
 41	    private static Database database;
 42	    private static Javalin app;
 43	    private static String base;
 44	
 45	    @BeforeAll
 46	    static void start() throws Exception {
 47	        String url = System.getenv("DB_URL");
 48	        assumeTrue(url != null && !url.isBlank(), "DB_URL não definido");
 49	        schema = "test_" + UUID.randomUUID().toString().replace("-", "");
 50	        exec(url, "CREATE SCHEMA " + schema);
 51	        database = new Database(url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema,
 52	                System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 53	        database.createSchema();
 54	        RoomCatalog rooms = RoomCatalog.standard();
 55	        app = new Api(new ReservationService(database, rooms), new ReportService(database), List.of(
 56	                new OccupancyReport(rooms), new RevenueReport(),
 57	                new TourismTaxReport(new BigDecimal("4.50")), new RatePlanReport())).create().start(0);
 58	        base = "http://localhost:" + app.port();
 59	    }
 60	
 61	    @AfterAll
 62	    static void stop() throws Exception {
 63	        if (app != null) app.stop();
 64	        if (database != null) database.close();
 65	        if (schema != null) exec(System.getenv("DB_URL"), "DROP SCHEMA " + schema + " CASCADE");
 66	    }
 67	
 68	    private static void exec(String url, String sql) throws Exception {
 69	        try (Connection c = DriverManager.getConnection(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 70	             Statement s = c.createStatement()) {
 71	            s.execute(sql);
 72	        }
 73	    }
 74	
 75	    private static HttpResponse<String> send(String method, String path, String body) throws Exception {
 76	        HttpRequest.BodyPublisher publisher = body == null
 77	                ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body);
 78	        return HTTP.send(HttpRequest.newBuilder(URI.create(base + path)).method(method, publisher).build(),
 79	                HttpResponse.BodyHandlers.ofString());
 80	    }
 81	
 82	    private static String booking(int room, String in, String out, int guests, String plan) {
 83	        return """
 84	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"carla@x.com","guestCpf":"111.222.333-44",
 85	                 "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}""".formatted(room, in, out, guests, plan);
 86	    }
 87	
 88	    private static long create(String body) throws Exception {
 89	        HttpResponse<String> r = send("POST", "/reservations", body);
 90	        assertEquals(201, r.statusCode(), r.body());
 91	        return JSON.readTree(r.body()).get("id").asLong();
 92	    }
 93	
 94	    private static void assertError(HttpResponse<String> r, int status, String code) throws Exception {
 95	        assertEquals(status, r.statusCode(), r.body());
 96	        assertEquals(code, JSON.readTree(r.body()).get("error").asText());
 97	    }
 98	
 99	    @Test
100	    void fullFlowWithConfirmationEmailAndReports() throws Exception {
101	        long id = create(booking(201, "2031-03-10", "2031-03-12", 2, "STANDARD"));
102	        JsonNode created = JSON.readTree(send("GET", "/reservations/" + id, null).body());
103	        assertEquals("PENDING", created.get("status").asText());
104	        assertEquals("779.80", created.get("total").asText());
105	        assertTrue(created.get("refund").isNull());
106	
107	        assertError(send("GET", "/reservations/" + id + "/document", null), 409, "OPERATION_NOT_ALLOWED");
108	        assertError(send("POST", "/reservations", booking(201, "2031-03-11", "2031-03-13", 2, "STANDARD")),
109	                409, "ROOM_UNAVAILABLE");
110	
111	        JsonNode confirmed = JSON.readTree(send("POST", "/reservations/" + id + "/confirmation", null).body());
112	        assertEquals("CONFIRMED", confirmed.get("status").asText());
113	        assertEquals("779.80", confirmed.get("amountPaid").asText());
114	
115	        JsonNode mine = null;
116	        for (JsonNode m : JSON.readTree(send("GET", "/messages", null).body())) {
117	            if (m.get("body").asText().contains("Comprovante de reserva nº " + id + "\n")) mine = m;
118	        }
119	        assertTrue(mine != null, "e-mail de confirmação não encontrado");
120	        assertEquals("EMAIL", mine.get("channel").asText());
121	        assertEquals("carla@x.com", mine.get("to").asText());
122	        assertEquals("Reserva confirmada - Pousada Maré Alta", mine.get("subject").asText());
123	        assertTrue(mine.get("body").asText().contains("Total: R$ 779,80"));
124	
125	        assertEquals(200, send("POST", "/reservations/" + id + "/check-in", null).statusCode());
126	        JsonNode receipt = JSON.readTree(send("POST", "/reservations/" + id + "/check-out", null).body());
127	        assertEquals("Comprovante de reserva", receipt.get("title").asText());
128	        assertEquals("DELUXE", receipt.get("roomType").asText());
129	        assertEquals(receipt, JSON.readTree(send("GET", "/reservations/" + id + "/document", null).body()));
130	
131	        HttpResponse<String> occupancy = send("GET", "/reports/occupancy?date=2031-03-11", null);
132	        assertEquals("text/csv; charset=utf-8", occupancy.headers().firstValue("content-type").orElse(""));
133	        assertTrue(occupancy.body().startsWith("Pousada Maré Alta,occupancy,2031-03-11\n"));
134	        assertTrue(occupancy.body().endsWith("total,1/5\n"));
135	        assertTrue(send("GET", "/reports/tourism-tax?month=2031-03", null).body().endsWith("total,18.00\n"));
136	        assertError(send("GET", "/reports/revenue?month=2031-3", null), 400, "INVALID_REQUEST");
137	    }
138	
139	    @Test
140	    void cancellationRefundsOnlyTheStandardPlan() throws Exception {
141	        long standard = create(booking(101, "2032-05-10", "2032-05-11", 1, "STANDARD"));
142	        long locked = create(booking(102, "2032-05-10", "2032-05-11", 1, "NON_REFUNDABLE"));
143	        send("POST", "/reservations/" + standard + "/confirmation", null);
144	        send("POST", "/reservations/" + locked + "/confirmation", null);
145	        JsonNode a = JSON.readTree(send("POST", "/reservations/" + standard + "/cancellation", null).body());
146	        JsonNode b = JSON.readTree(send("POST", "/reservations/" + locked + "/cancellation", null).body());
147	        assertEquals("249.90", a.get("refund").asText());
148	        assertEquals("0.00", b.get("refund").asText());
149	        assertError(send("POST", "/reservations/" + standard + "/cancellation", null), 409, "OPERATION_NOT_ALLOWED");
150	        // o quarto cancelado volta a ficar livre
151	        create(booking(101, "2032-05-10", "2032-05-11", 1, "STANDARD"));
152	        String revenue = send("GET", "/reports/revenue?month=2032-05", null).body();
153	        assertTrue(revenue.contains("CANCELLED,212.42"), revenue);
154	        assertTrue(revenue.endsWith("total,212.42\n"), revenue);
155	        assertTrue(send("GET", "/reports/rate-plans?month=2032-05", null).body()
156	                .endsWith("STANDARD,0,0.00\nNON_REFUNDABLE,1,212.42\ntotal,1,212.42\n"));
157	    }
158	
159	    @Test
160	    void invalidRequests() throws Exception {
161	        assertError(send("POST", "/reservations", "não é json"), 400, "INVALID_REQUEST");
162	        assertError(send("POST", "/reservations", booking(101, "2033-01-10", "2033-01-10", 1, "STANDARD")),
163	                400, "INVALID_REQUEST");
164	        assertError(send("POST", "/reservations", booking(101, "2033-01-10", "2033-01-11", 0, "STANDARD")),
165	                400, "INVALID_REQUEST");
166	        assertError(send("POST", "/reservations", booking(101, "2033-01-10", "2033-01-11", 1, "OTHER")),
167	                400, "INVALID_REQUEST");
168	        assertError(send("POST", "/reservations", "{\"roomNumber\":101}"), 400, "INVALID_REQUEST");
169	        assertError(send("POST", "/reservations", booking(999, "2033-01-10", "2033-01-11", 1, "STANDARD")),
170	                404, "ROOM_NOT_FOUND");
171	        assertError(send("POST", "/reservations", booking(101, "2033-01-10", "2033-01-11", 3, "STANDARD")),
172	                422, "CAPACITY_EXCEEDED");
173	        assertError(send("GET", "/reservations/999999", null), 404, "RESERVATION_NOT_FOUND");
174	        assertError(send("POST", "/reservations/999999/confirmation", null), 404, "RESERVATION_NOT_FOUND");
175	    }
176	
177	    @Test
178	    void listsTheFiveRooms() throws Exception {
179	        JsonNode rooms = JSON.readTree(send("GET", "/rooms", null).body());
180	        assertEquals(5, rooms.size());
181	        assertEquals("579.90", rooms.get(4).get("nightlyRate").asText());
182	    }
183	}

